INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'colours-clothing', 'A1', 'Colours & Clothing', 'Farben & Kleidung', 'everyday', 'Name colours and clothes and describe what people are wearing.', 1) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Im Kleidergeschäft', '{"title":"Im Kleidergeschäft","lines":[{"speaker":"Verkäufer","de":"Guten Tag, suchen Sie etwas Bestimmtes?","en":"Hello, are you looking for something particular?"},{"speaker":"Kundin","de":"Ja, ich suche eine blaue Jacke.","en":"Yes, I am looking for a blue jacket."},{"speaker":"Verkäufer","de":"Welche Größe haben Sie?","en":"What size are you?"},{"speaker":"Kundin","de":"Größe achtunddreißig, bitte.","en":"Size thirty-eight, please."}],"question":"What is the customer looking for?","options":["A blue jacket","Red shoes","A green shirt"],"answer":0}'::jsonb, 'Colour adjectives before a noun take an ending: eine blaue Jacke.', 100) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Lieblingspullover', '{"title":"Mein Lieblingspullover","text_de":"Mein Lieblingspullover ist grau und sehr warm. Dazu trage ich oft eine schwarze Hose. Im Sommer trage ich lieber ein weißes T-Shirt.","text_en":"My favourite jumper is grey and very warm. With it I often wear black trousers. In summer I prefer a white T-shirt.","question":"What colour is the jumper?","options":["Black","Grey","White"],"answer":1}'::jsonb, 'tragen is the verb for wearing clothes.', 101) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich trage eine rote Jacke.","en":"I am wearing a red jacket.","stress":"ich TRA-ge EI-ne RO-te YA-cke","tip":"The German j in Jacke sounds like the English y."}'::jsonb, 'Stress pattern: ich TRA-ge EI-ne RO-te YA-cke', 102) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich möchte ___ blaues Hemd.","en":"I would like a blue shirt.","options":["ein","eine","einen"],"answer":0}'::jsonb, 'das Hemd is neuter, so ein blaues Hemd.', 103) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Sie","trägt","einen","grünen","Mantel"],"answer":["Sie","trägt","einen","grünen","Mantel"],"en":"She is wearing a green coat."}'::jsonb, 'Masculine accusative: einen grünen Mantel.', 104) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Jacke","en":"the jacket"},{"de":"die Hose","en":"the trousers"},{"de":"rot","en":"red"},{"de":"gelb","en":"yellow"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 105) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Die Schuhe sind ___.","en":"The shoes are black.","options":["schwarz","schwarze","schwarzen"],"answer":0}'::jsonb, 'After sein the adjective takes no ending.', 106) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A shop assistant asks if you need help but you just want to browse.","question":"What do you say?","options":["Nein.","Danke, ich schaue mich nur um.","Lassen Sie mich."],"answer":1}'::jsonb, 'Ich schaue mich nur um is the standard polite phrase.', 107) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('1aad295e-aa56-5268-ac49-681a6202abc6'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was tragen Sie heute? Schreiben Sie drei Sätze.', '{"prompt":"Was tragen Sie heute? Schreiben Sie drei Sätze.","hint":"Use: Ich trage …, Dazu …, Meine Lieblingsfarbe ist …","sample":"Ich trage heute eine blaue Hose und ein weißes Hemd. Dazu trage ich schwarze Schuhe. Meine Lieblingsfarbe ist grün."}'::jsonb, 'Use the hint and compare your answer with the model.', 108) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'shopping', 'A1', 'Shopping & Prices', 'Einkaufen & Preise', 'everyday', 'Ask for prices, quantities and pay at the checkout.', 2) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: An der Kasse', '{"title":"An der Kasse","lines":[{"speaker":"Kassiererin","de":"Das macht zwölf Euro fünfzig.","en":"That comes to twelve euros fifty."},{"speaker":"Kunde","de":"Kann ich mit Karte zahlen?","en":"Can I pay by card?"},{"speaker":"Kassiererin","de":"Ja, gern. Brauchen Sie eine Tüte?","en":"Yes, of course. Do you need a bag?"},{"speaker":"Kunde","de":"Nein danke, ich habe eine Tasche.","en":"No thanks, I have a bag."}],"question":"How much does it cost?","options":["12.15","12.50","20.50"],"answer":1}'::jsonb, 'Das macht … is how cashiers announce the total.', 200) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Im Supermarkt', '{"title":"Im Supermarkt","text_de":"Am Samstag kaufe ich im Supermarkt ein. Ich brauche Milch, Brot und Obst. Das Gemüse ist heute im Angebot.","text_en":"On Saturday I shop in the supermarket. I need milk, bread and fruit. The vegetables are on offer today.","question":"What is on offer?","options":["Bread","Vegetables","Milk"],"answer":1}'::jsonb, 'im Angebot means on special offer.', 201) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Was kostet das, bitte?","en":"What does that cost, please?","stress":"was KOS-tet das BI-tte","tip":"The s in kostet is sharp; keep bitte short and even."}'::jsonb, 'Stress pattern: was KOS-tet das BI-tte', 202) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ kostet ein Kilo Äpfel?","en":"How much is a kilo of apples?","options":["Was","Wer","Wo"],"answer":0}'::jsonb, 'Was kostet …? asks for a price.', 203) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","möchte","bitte","zwei","Brötchen"],"answer":["Ich","möchte","bitte","zwei","Brötchen"],"en":"I would like two bread rolls, please."}'::jsonb, 'bitte usually sits in the middle of the sentence.', 204) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Kasse","en":"the checkout"},{"de":"das Angebot","en":"the offer"},{"de":"billig","en":"cheap"},{"de":"teuer","en":"expensive"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 205) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich hätte gern ___ Liter Milch.","en":"I would like one litre of milk.","options":["einen","ein","eine"],"answer":1}'::jsonb, 'der Liter is masculine but here it is the accusative measure: einen Liter is also common; ein Liter Milch works as a quantity.', 206) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"The cashier says a total you did not understand.","question":"What do you say?","options":["Was?","Entschuldigung, wie viel bitte?","Nochmal!"],"answer":1}'::jsonb, 'Entschuldigung softens a request to repeat.', 207) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('a315cc97-36ce-5d0f-a949-ec361624e72e'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was kaufen Sie jede Woche ein? Drei Sätze.', '{"prompt":"Was kaufen Sie jede Woche ein? Drei Sätze.","hint":"Use: Ich kaufe …, Ich brauche …, … ist teuer/billig.","sample":"Ich kaufe jede Woche Brot und Käse. Ich brauche auch Kaffee und Obst. Fleisch ist bei uns ziemlich teuer."}'::jsonb, 'Use the hint and compare your answer with the model.', 208) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'bakery-cafe', 'A1', 'At the Bakery & Café', 'Bäckerei & Café', 'food', 'Order rolls, cake and coffee like a local.', 3) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: In der Bäckerei', '{"title":"In der Bäckerei","lines":[{"speaker":"Bäckerin","de":"Was darf es sein?","en":"What can I get you?"},{"speaker":"Gast","de":"Drei Brötchen und ein Stück Kuchen, bitte.","en":"Three rolls and a piece of cake, please."},{"speaker":"Bäckerin","de":"Sonst noch etwas?","en":"Anything else?"},{"speaker":"Gast","de":"Nein, das ist alles.","en":"No, that is all."}],"question":"What does the guest order?","options":["Rolls and cake","Bread and coffee","Only cake"],"answer":0}'::jsonb, 'Was darf es sein? is the classic bakery greeting.', 300) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Kaffee und Kuchen', '{"title":"Kaffee und Kuchen","text_de":"Am Sonntagnachmittag gibt es bei uns Kaffee und Kuchen. Meine Oma backt einen Apfelkuchen. Wir sitzen lange am Tisch und reden.","text_en":"On Sunday afternoon we have coffee and cake. My grandma bakes an apple cake. We sit at the table for a long time and talk.","question":"Who bakes the cake?","options":["Mother","Grandma","Uncle"],"answer":1}'::jsonb, 'Kaffee und Kuchen is a German Sunday tradition.', 301) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ein Stück Kuchen, bitte.","en":"A piece of cake, please.","stress":"ein SCHTÜCK KU-chen BI-tte","tip":"st at the start of a word sounds like scht."}'::jsonb, 'Stress pattern: ein SCHTÜCK KU-chen BI-tte', 302) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich nehme ___ Kaffee.","en":"I will take a coffee.","options":["ein","einen","eine"],"answer":1}'::jsonb, 'der Kaffee is masculine, accusative einen.', 303) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","hätte","gern","zwei","Stück","Kuchen"],"answer":["Ich","hätte","gern","zwei","Stück","Kuchen"],"en":"I would like two pieces of cake."}'::jsonb, 'Stück stays singular after numbers.', 304) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Brötchen","en":"the bread roll"},{"de":"der Kuchen","en":"the cake"},{"de":"die Sahne","en":"the cream"},{"de":"zum Mitnehmen","en":"to take away"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 305) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"___ noch etwas?","en":"Anything else?","options":["Sonst","Immer","Auch"],"answer":0}'::jsonb, 'Sonst noch etwas? is the fixed phrase.', 306) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You want your coffee to take away.","question":"How do you say it?","options":["Kaffee, weg!","Einen Kaffee zum Mitnehmen, bitte.","Kaffee gehen."],"answer":1}'::jsonb, 'zum Mitnehmen is the standard phrase for takeaway.', 307) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('4781e7ad-0d7e-5b07-a5b2-5e6f3981cafd'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Bestellen Sie schriftlich in einem Café. Drei Sätze.', '{"prompt":"Bestellen Sie schriftlich in einem Café. Drei Sätze.","hint":"Use: Ich hätte gern …, Und dazu …, Zahlen bitte.","sample":"Ich hätte gern einen Tee mit Zitrone. Und dazu ein Stück Apfelkuchen, bitte. Zahlen bitte, mit Karte."}'::jsonb, 'Use the hint and compare your answer with the model.', 308) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'weather', 'A1', 'Weather & Seasons', 'Wetter & Jahreszeiten', 'smalltalk', 'Describe the weather and the seasons in simple sentences.', 4) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wie ist das Wetter?', '{"title":"Wie ist das Wetter?","lines":[{"speaker":"Ali","de":"Wie ist das Wetter heute?","en":"What is the weather like today?"},{"speaker":"Mia","de":"Es ist kalt und es regnet.","en":"It is cold and it is raining."},{"speaker":"Ali","de":"Und morgen?","en":"And tomorrow?"},{"speaker":"Mia","de":"Morgen wird es sonnig.","en":"Tomorrow it will be sunny."}],"question":"What is the weather today?","options":["Sunny","Cold and rainy","Snowy"],"answer":1}'::jsonb, 'Weather sentences start with the impersonal es.', 400) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die Jahreszeiten', '{"title":"Die Jahreszeiten","text_de":"Im Frühling wird es wärmer und die Blumen blühen. Der Sommer ist heiß. Im Herbst regnet es oft, und im Winter schneit es manchmal.","text_en":"In spring it gets warmer and the flowers bloom. Summer is hot. In autumn it often rains, and in winter it sometimes snows.","question":"When does it snow?","options":["In winter","In spring","In autumn"],"answer":0}'::jsonb, 'Seasons take im: im Frühling, im Sommer.', 401) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Heute scheint die Sonne.","en":"The sun is shining today.","stress":"HEU-te SCHEINT die SO-nne","tip":"eu sounds like oy; sch is a single sh sound."}'::jsonb, 'Stress pattern: HEU-te SCHEINT die SO-nne', 402) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Es ___ heute stark.","en":"It is raining heavily today.","options":["regnet","regnen","geregnet"],"answer":0}'::jsonb, 'es takes the third person singular regnet.', 403) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Morgen","wird","es","warm","und","sonnig"],"answer":["Morgen","wird","es","warm","und","sonnig"],"en":"Tomorrow it will be warm and sunny."}'::jsonb, 'Time word first, verb second.', 404) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Regen","en":"the rain"},{"de":"der Schnee","en":"the snow"},{"de":"bewölkt","en":"cloudy"},{"de":"windig","en":"windy"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 405) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"___ Winter ist es kalt.","en":"In winter it is cold.","options":["In","Im","Am"],"answer":1}'::jsonb, 'Seasons use im.', 406) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You want to start small talk with a neighbour at the bus stop.","question":"What is a natural opener?","options":["Sie sehen müde aus.","Ganz schön kalt heute, oder?","Wie viel verdienen Sie?"],"answer":1}'::jsonb, 'Weather is the safest small talk topic in Germany.', 407) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('f71e2ff0-f0b5-50f6-a587-11dd79ba983d'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wie ist das Wetter bei Ihnen? Drei Sätze.', '{"prompt":"Wie ist das Wetter bei Ihnen? Drei Sätze.","hint":"Use: Heute ist es …, Im Sommer …, Ich mag … Wetter.","sample":"Heute ist es bewölkt und windig. Im Sommer wird es hier sehr heiß. Ich mag sonniges Wetter am liebsten."}'::jsonb, 'Use the hint and compare your answer with the model.', 408) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'days-months', 'A1', 'Days, Months & Dates', 'Tage, Monate & Datum', 'time', 'Say dates, birthdays and days of the week.', 5) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wann hast du Geburtstag?', '{"title":"Wann hast du Geburtstag?","lines":[{"speaker":"Emma","de":"Wann hast du Geburtstag?","en":"When is your birthday?"},{"speaker":"Nils","de":"Am dritten Mai. Und du?","en":"On the third of May. And you?"},{"speaker":"Emma","de":"Im Dezember, am zwanzigsten.","en":"In December, on the twentieth."}],"question":"When is Nils''s birthday?","options":["3 May","20 December","13 March"],"answer":0}'::jsonb, 'Dates use am plus an ordinal number.', 500) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Wochenplan', '{"title":"Mein Wochenplan","text_de":"Am Montag arbeite ich lange. Am Mittwoch gehe ich zum Deutschkurs. Am Wochenende besuche ich meine Familie.","text_en":"On Monday I work long hours. On Wednesday I go to the German course. At the weekend I visit my family.","question":"When is the German course?","options":["Monday","Wednesday","Sunday"],"answer":1}'::jsonb, 'Days of the week take am.', 501) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Am Dienstag habe ich Zeit.","en":"On Tuesday I have time.","stress":"am DIENS-tag HA-be ich TSEIT","tip":"The z in Zeit is a ts sound."}'::jsonb, 'Stress pattern: am DIENS-tag HA-be ich TSEIT', 502) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ Freitag gehe ich ins Kino.","en":"On Friday I go to the cinema.","options":["Am","Im","An"],"answer":0}'::jsonb, 'Days take am.', 503) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Mein","Kurs","beginnt","am","ersten","September"],"answer":["Mein","Kurs","beginnt","am","ersten","September"],"en":"My course starts on the first of September."}'::jsonb, 'am + ordinal + month for dates.', 504) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Montag","en":"Monday"},{"de":"der Monat","en":"the month"},{"de":"das Datum","en":"the date"},{"de":"das Wochenende","en":"the weekend"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 505) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich habe ___ Juli Urlaub.","en":"I have holiday in July.","options":["am","im","um"],"answer":1}'::jsonb, 'Months take im.', 506) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You must give your date of birth on the phone to an office.","question":"What is clearest?","options":["Mai drei.","Ich bin am dritten Mai neunzehnhundertneunzig geboren.","Dreißig fünf."],"answer":1}'::jsonb, 'Full sentences avoid misunderstandings on the phone.', 507) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2606f2d7-199d-5211-a016-0ade9700ff16'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihre Woche. Drei Sätze mit Tagen.', '{"prompt":"Beschreiben Sie Ihre Woche. Drei Sätze mit Tagen.","hint":"Use: Am Montag …, Am Donnerstag …, Am Wochenende …","sample":"Am Montag arbeite ich von acht bis fünf. Am Donnerstag gehe ich zum Sport. Am Wochenende koche ich mit Freunden."}'::jsonb, 'Use the hint and compare your answer with the model.', 508) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'hobbies', 'A1', 'Hobbies & Free Time', 'Hobbys & Freizeit', 'leisure', 'Say what you like doing with gern and your free time.', 6) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Was machst du gern?', '{"title":"Was machst du gern?","lines":[{"speaker":"Ana","de":"Was machst du gern in deiner Freizeit?","en":"What do you like doing in your free time?"},{"speaker":"Timo","de":"Ich spiele gern Fußball und lese viel.","en":"I like playing football and read a lot."},{"speaker":"Ana","de":"Ich tanze lieber.","en":"I prefer dancing."}],"question":"What does Timo like?","options":["Dancing","Football and reading","Cooking"],"answer":1}'::jsonb, 'gern after the verb expresses liking an activity.', 600) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Meine Freizeit', '{"title":"Meine Freizeit","text_de":"Nach der Arbeit gehe ich oft schwimmen. Am Wochenende treffe ich Freunde oder höre Musik. Manchmal fahre ich mit dem Rad ins Grüne.","text_en":"After work I often go swimming. At the weekend I meet friends or listen to music. Sometimes I cycle out into the countryside.","question":"What does the writer do after work?","options":["Swim","Cook","Study"],"answer":0}'::jsonb, 'gehen + infinitive: schwimmen gehen.', 601) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich höre gern Musik.","en":"I like listening to music.","stress":"ich HÖ-re gern mu-SIK","tip":"ö is rounded; Musik stresses the second syllable."}'::jsonb, 'Stress pattern: ich HÖ-re gern mu-SIK', 602) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich spiele ___ Gitarre.","en":"I like playing the guitar.","options":["gern","gut","viel"],"answer":0}'::jsonb, 'gern expresses enjoyment.', 603) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Am","Wochenende","spiele","ich","gern","Tennis"],"answer":["Am","Wochenende","spiele","ich","gern","Tennis"],"en":"At the weekend I like playing tennis."}'::jsonb, 'Time phrase first, verb second.', 604) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Freizeit","en":"the free time"},{"de":"das Hobby","en":"the hobby"},{"de":"malen","en":"to paint"},{"de":"wandern","en":"to hike"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 605) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Am liebsten ___ ich ins Kino.","en":"Most of all I go to the cinema.","options":["gehe","gehen","geht"],"answer":0}'::jsonb, 'The verb comes second after am liebsten.', 606) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A new classmate asks about your hobbies.","question":"Which answer keeps the conversation going?","options":["Nichts.","Ich koche gern. Und du?","Frag nicht."],"answer":1}'::jsonb, 'Answer plus a return question builds rapport.', 607) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('ec781520-f61d-539d-afba-93026a32b10b'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was machen Sie gern in der Freizeit? Drei Sätze.', '{"prompt":"Was machen Sie gern in der Freizeit? Drei Sätze.","hint":"Use: Ich … gern, Manchmal …, Am liebsten …","sample":"Ich lese gern Krimis. Manchmal gehe ich mit Freunden ins Schwimmbad. Am liebsten koche ich am Wochenende."}'::jsonb, 'Use the hint and compare your answer with the model.', 608) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'home-rooms', 'A1', 'My Home', 'Meine Wohnung', 'home', 'Describe rooms and where you live.', 7) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Deine neue Wohnung', '{"title":"Deine neue Wohnung","lines":[{"speaker":"Jana","de":"Wie ist deine neue Wohnung?","en":"What is your new flat like?"},{"speaker":"Omar","de":"Klein, aber hell. Sie hat zwei Zimmer.","en":"Small but bright. It has two rooms."},{"speaker":"Jana","de":"Und wo liegt sie?","en":"And where is it?"},{"speaker":"Omar","de":"Im Zentrum, neben dem Park.","en":"In the centre, next to the park."}],"question":"Where is the flat?","options":["In the centre","Outside town","By the station"],"answer":0}'::jsonb, 'liegen is used for the position of buildings and places.', 700) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Zu Hause', '{"title":"Zu Hause","text_de":"Unsere Wohnung hat drei Zimmer, eine Küche und ein Bad. Das Wohnzimmer ist groß und hell. Mein Zimmer ist klein, aber gemütlich.","text_en":"Our flat has three rooms, a kitchen and a bathroom. The living room is big and bright. My room is small but cosy.","question":"How is the living room?","options":["Small","Big and bright","Dark"],"answer":1}'::jsonb, 'aber links two contrasting adjectives.', 701) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Die Küche ist sehr klein.","en":"The kitchen is very small.","stress":"die KÜ-che ist sehr KLEIN","tip":"ü is rounded; the ch after ü is the soft ich-Laut."}'::jsonb, 'Stress pattern: die KÜ-che ist sehr KLEIN', 702) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich wohne ___ einer Wohnung.","en":"I live in a flat.","options":["in","an","auf"],"answer":0}'::jsonb, 'wohnen in + dative.', 703) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Meine","Wohnung","hat","einen","Balkon"],"answer":["Meine","Wohnung","hat","einen","Balkon"],"en":"My flat has a balcony."}'::jsonb, 'haben takes the accusative: einen Balkon.', 704) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Zimmer","en":"the room"},{"de":"die Küche","en":"the kitchen"},{"de":"der Flur","en":"the hallway"},{"de":"gemütlich","en":"cosy"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 705) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Das Bad ist ___ Küche.","en":"The bathroom is next to the kitchen.","options":["neben der","neben die","neben"],"answer":0}'::jsonb, 'Position takes the dative: neben der Küche.', 706) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A guest visits your home for the first time.","question":"What do you say at the door?","options":["Komm rein, herzlich willkommen!","Schuhe aus, sofort.","Was willst du?"],"answer":0}'::jsonb, 'A warm welcome first; you can mention shoes afterwards.', 707) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('2cddd7b2-f880-578a-ac31-35a419ae3ff6'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihre Wohnung. Drei Sätze.', '{"prompt":"Beschreiben Sie Ihre Wohnung. Drei Sätze.","hint":"Use: Meine Wohnung hat …, Das … ist …, Ich wohne …","sample":"Meine Wohnung hat zwei Zimmer und eine kleine Küche. Das Wohnzimmer ist hell und gemütlich. Ich wohne im dritten Stock."}'::jsonb, 'Use the hint and compare your answer with the model.', 708) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'furniture', 'A1', 'Furniture & Prepositions', 'Möbel & Präpositionen', 'home', 'Say where furniture stands with auf, unter and neben.', 8) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Wo ist mein Handy?', '{"title":"Wo ist mein Handy?","lines":[{"speaker":"Lukas","de":"Wo ist mein Handy?","en":"Where is my phone?"},{"speaker":"Sara","de":"Es liegt auf dem Tisch.","en":"It is lying on the table."},{"speaker":"Lukas","de":"Und meine Schlüssel?","en":"And my keys?"},{"speaker":"Sara","de":"Die sind in der Schublade.","en":"They are in the drawer."}],"question":"Where is the phone?","options":["In the drawer","On the table","Under the sofa"],"answer":1}'::jsonb, 'liegen for flat objects, stehen for upright ones.', 800) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Zimmer', '{"title":"Mein Zimmer","text_de":"Mein Bett steht am Fenster. Neben dem Bett steht ein kleiner Schrank. Unter dem Schreibtisch liegt ein Teppich.","text_en":"My bed stands by the window. Next to the bed is a small cupboard. Under the desk lies a rug.","question":"What is under the desk?","options":["A rug","A chair","A box"],"answer":0}'::jsonb, 'Positions always take the dative.', 801) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Der Stuhl steht neben dem Tisch.","en":"The chair is next to the table.","stress":"der SCHTUHL schteht NE-ben dem TISCH","tip":"st at the start of a word is scht."}'::jsonb, 'Stress pattern: der SCHTUHL schteht NE-ben dem TISCH', 802) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Die Lampe steht ___ Schreibtisch.","en":"The lamp is on the desk.","options":["auf dem","auf den","auf der"],"answer":0}'::jsonb, 'Position: auf + dative.', 803) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Der","Fernseher","steht","in","der","Ecke"],"answer":["Der","Fernseher","steht","in","der","Ecke"],"en":"The television is in the corner."}'::jsonb, 'stehen with a dative place phrase.', 804) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Schrank","en":"the cupboard"},{"de":"das Regal","en":"the shelf"},{"de":"der Sessel","en":"the armchair"},{"de":"der Teppich","en":"the rug"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 805) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Die Katze schläft ___ Sofa.","en":"The cat sleeps under the sofa.","options":["unter dem","unter das","unter der"],"answer":0}'::jsonb, 'das Sofa becomes dem Sofa in the dative.', 806) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are helping a friend move furniture.","question":"Which sentence is helpful and polite?","options":["Mach schneller.","Soll der Schrank neben das Fenster?","Ist mir egal."],"answer":1}'::jsonb, 'A question checks the plan before heavy lifting.', 807) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('66559762-2de4-5f86-a192-8ab569c23700'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wo stehen die Möbel in Ihrem Zimmer? Drei Sätze.', '{"prompt":"Wo stehen die Möbel in Ihrem Zimmer? Drei Sätze.","hint":"Use: … steht …, Neben dem …, Unter dem …","sample":"Mein Bett steht neben der Tür. Neben dem Bett steht ein kleines Regal. Unter dem Fenster steht ein Schreibtisch."}'::jsonb, 'Use the hint and compare your answer with the model.', 808) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'jobs', 'A1', 'Jobs & Professions', 'Berufe', 'work', 'Say what you do for a living and where you work.', 9) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Was machen Sie beruflich?', '{"title":"Was machen Sie beruflich?","lines":[{"speaker":"Frau Roth","de":"Was machen Sie beruflich?","en":"What do you do for a living?"},{"speaker":"Herr Diaz","de":"Ich bin Krankenpfleger im Krankenhaus.","en":"I am a nurse at the hospital."},{"speaker":"Frau Roth","de":"Und arbeiten Sie Vollzeit?","en":"And do you work full time?"},{"speaker":"Herr Diaz","de":"Nein, dreißig Stunden pro Woche.","en":"No, thirty hours a week."}],"question":"Where does Herr Diaz work?","options":["In a school","In a hospital","In an office"],"answer":1}'::jsonb, 'Professions take no article: Ich bin Krankenpfleger.', 900) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Berufe in meiner Familie', '{"title":"Berufe in meiner Familie","text_de":"Meine Mutter ist Lehrerin an einer Grundschule. Mein Vater arbeitet als Techniker bei einer Firma. Meine Schwester studiert noch.","text_en":"My mother is a teacher at a primary school. My father works as a technician at a company. My sister is still studying.","question":"What does the father do?","options":["Teacher","Technician","Student"],"answer":1}'::jsonb, 'arbeiten als + profession without an article.', 901) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich arbeite als Verkäuferin.","en":"I work as a sales assistant.","stress":"ich AR-bei-te als fer-KÄU-fe-rin","tip":"The v in Verkäuferin sounds like f; äu sounds like oy."}'::jsonb, 'Stress pattern: ich AR-bei-te als fer-KÄU-fe-rin', 902) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich bin ___ Beruf Köchin.","en":"I am a cook by profession.","options":["von","in","als"],"answer":0}'::jsonb, 'The fixed phrase is von Beruf.', 903) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","arbeite","seit","zwei","Jahren","hier"],"answer":["Ich","arbeite","seit","zwei","Jahren","hier"],"en":"I have been working here for two years."}'::jsonb, 'seit + dative with the present tense.', 904) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Beruf","en":"the profession"},{"de":"die Firma","en":"the company"},{"de":"die Stelle","en":"the position"},{"de":"die Kollegin","en":"the colleague"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 905) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Er arbeitet ___ einer Bank.","en":"He works at a bank.","options":["bei","in","an"],"answer":0}'::jsonb, 'bei + employer, in + building.', 906) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"At a party a stranger asks what you do.","question":"Which reply is natural in German?","options":["Ich bin Ingenieurin, und Sie?","Ich verdiene gut.","Warum fragen Sie?"],"answer":0}'::jsonb, 'State the job briefly and return the question.', 907) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('d90ee370-2217-5ed3-a1d2-8246771ee3f0'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihren Beruf oder Ihren Wunschberuf. Drei Sätze.', '{"prompt":"Beschreiben Sie Ihren Beruf oder Ihren Wunschberuf. Drei Sätze.","hint":"Use: Ich bin …, Ich arbeite bei/in …, Meine Arbeit ist …","sample":"Ich bin Programmiererin von Beruf. Ich arbeite bei einer kleinen Firma in Köln. Meine Arbeit ist anstrengend, aber interessant."}'::jsonb, 'Use the hint and compare your answer with the model.', 908) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'school-course', 'A1', 'School & Language Course', 'Schule & Sprachkurs', 'learning', 'Handle classroom language and talk about learning German.', 10) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Im Deutschkurs', '{"title":"Im Deutschkurs","lines":[{"speaker":"Lehrerin","de":"Haben Sie eine Frage?","en":"Do you have a question?"},{"speaker":"Teilnehmer","de":"Ja, wie schreibt man das Wort?","en":"Yes, how do you write that word?"},{"speaker":"Lehrerin","de":"Ich schreibe es an die Tafel.","en":"I will write it on the board."},{"speaker":"Teilnehmer","de":"Danke, jetzt verstehe ich.","en":"Thanks, now I understand."}],"question":"What does the participant ask?","options":["How to write the word","The price","The homework"],"answer":0}'::jsonb, 'Wie schreibt man …? uses the impersonal man.', 1000) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Kurs', '{"title":"Mein Kurs","text_de":"Mein Deutschkurs beginnt um neun Uhr. Wir sind zwölf Teilnehmer aus acht Ländern. Die Hausaufgaben mache ich abends.","text_en":"My German course starts at nine. We are twelve participants from eight countries. I do the homework in the evening.","question":"How many participants are there?","options":["Eight","Twelve","Nine"],"answer":1}'::jsonb, 'aus + country for origin.', 1001) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Können Sie das bitte wiederholen?","en":"Can you repeat that, please?","stress":"KÖ-nnen sie das BI-tte wie-der-HO-len","tip":"wiederholen stresses -ho-, not the prefix."}'::jsonb, 'Stress pattern: KÖ-nnen sie das BI-tte wie-der-HO-len', 1002) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Wie ___ man das auf Deutsch?","en":"How do you say that in German?","options":["sagt","sagen","gesagt"],"answer":0}'::jsonb, 'man takes the third person singular.', 1003) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","lerne","seit","einem","Jahr","Deutsch"],"answer":["Ich","lerne","seit","einem","Jahr","Deutsch"],"en":"I have been learning German for a year."}'::jsonb, 'seit + dative with the present tense.', 1004) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Aufgabe","en":"the task"},{"de":"die Tafel","en":"the board"},{"de":"das Wort","en":"the word"},{"de":"üben","en":"to practise"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1005) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich verstehe das Wort ___.","en":"I do not understand the word.","options":["nicht","kein","nichts"],"answer":0}'::jsonb, 'nicht negates a verb; kein negates a noun.', 1006) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"The teacher speaks too fast for you.","question":"What do you say?","options":["Sie sprechen zu schnell!","Könnten Sie bitte etwas langsamer sprechen?","Ich verstehe nichts."],"answer":1}'::jsonb, 'A polite request is more effective than criticism.', 1007) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('e0ce4003-1e17-5e8d-ad93-3903a8e05114'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Warum lernen Sie Deutsch? Drei Sätze.', '{"prompt":"Warum lernen Sie Deutsch? Drei Sätze.","hint":"Use: Ich lerne Deutsch, weil …, Mein Kurs …, Ich übe …","sample":"Ich lerne Deutsch, weil ich hier arbeiten möchte. Mein Kurs ist am Abend von sechs bis acht. Ich übe jeden Tag zwanzig Minuten."}'::jsonb, 'Use the hint and compare your answer with the model.', 1008) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'body-health', 'A1', 'Body & Feeling Unwell', 'Körper & Beschwerden', 'health', 'Name body parts and say what hurts.', 11) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Was fehlt dir?', '{"title":"Was fehlt dir?","lines":[{"speaker":"Ute","de":"Du siehst müde aus. Was fehlt dir?","en":"You look tired. What is wrong?"},{"speaker":"Jan","de":"Mein Kopf tut weh.","en":"My head hurts."},{"speaker":"Ute","de":"Trink viel Wasser und ruh dich aus.","en":"Drink a lot of water and rest."}],"question":"What is wrong with Jan?","options":["Headache","Stomach ache","Sore throat"],"answer":0}'::jsonb, '… tut weh is the standard way to say something hurts.', 1100) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Erkältet', '{"title":"Erkältet","text_de":"Ich bin erkältet. Mein Hals tut weh und ich huste viel. Ich trinke Tee mit Honig und bleibe zu Hause.","text_en":"I have a cold. My throat hurts and I cough a lot. I drink tea with honey and stay at home.","question":"What does the writer drink?","options":["Coffee","Tea with honey","Juice"],"answer":1}'::jsonb, 'erkältet sein means to have a cold.', 1101) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Mein Rücken tut weh.","en":"My back hurts.","stress":"mein RÜ-cken tut WEH","tip":"ü is rounded; weh has a long open e."}'::jsonb, 'Stress pattern: mein RÜ-cken tut WEH', 1102) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Meine Augen ___ weh.","en":"My eyes hurt.","options":["tun","tut","tue"],"answer":0}'::jsonb, 'Plural subject takes tun.', 1103) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","habe","seit","gestern","Halsschmerzen"],"answer":["Ich","habe","seit","gestern","Halsschmerzen"],"en":"I have had a sore throat since yesterday."}'::jsonb, 'seit + dative for a duration up to now.', 1104) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Kopf","en":"the head"},{"de":"der Bauch","en":"the stomach"},{"de":"die Schmerzen","en":"the pain"},{"de":"die Erkältung","en":"the cold"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1105) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich habe ___ .","en":"I have a fever.","options":["Fieber","kalt","krank"],"answer":0}'::jsonb, 'Fieber haben is the fixed expression.', 1106) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are too ill to come to work.","question":"What do you tell your manager?","options":["Komme nicht.","Ich bin krank und gehe heute zum Arzt. Ich melde mich am Nachmittag.","Bin heute weg."],"answer":1}'::jsonb, 'State the reason and promise an update.', 1107) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('cc335fe1-e23c-5acb-a3f2-e7667f2207e8'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Sie sind krank. Schreiben Sie eine kurze Nachricht.', '{"prompt":"Sie sind krank. Schreiben Sie eine kurze Nachricht.","hint":"Use: Ich bin …, Ich habe …, Ich hoffe …","sample":"Hallo Frau Bauer, ich bin heute krank. Ich habe Fieber und Halsschmerzen. Ich hoffe, dass ich morgen wieder da bin."}'::jsonb, 'Use the hint and compare your answer with the model.', 1108) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'doctor', 'A1', 'At the Doctor', 'Beim Arzt', 'health', 'Make an appointment and describe symptoms at the practice.', 12) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: In der Praxis', '{"title":"In der Praxis","lines":[{"speaker":"Sprechstundenhilfe","de":"Haben Sie einen Termin?","en":"Do you have an appointment?"},{"speaker":"Patientin","de":"Nein, aber ich habe starke Schmerzen.","en":"No, but I am in a lot of pain."},{"speaker":"Sprechstundenhilfe","de":"Haben Sie Ihre Versichertenkarte dabei?","en":"Do you have your insurance card with you?"},{"speaker":"Patientin","de":"Ja, hier bitte.","en":"Yes, here you are."}],"question":"What does the assistant ask for?","options":["Insurance card","Passport","Payment"],"answer":0}'::jsonb, 'Die Versichertenkarte is required at every German practice.', 1200) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die Untersuchung', '{"title":"Die Untersuchung","text_de":"Der Arzt untersucht mich und misst das Fieber. Er sagt, ich soll drei Tage im Bett bleiben. Er schreibt mir ein Rezept.","text_en":"The doctor examines me and takes my temperature. He says I should stay in bed for three days. He writes me a prescription.","question":"What does the doctor recommend?","options":["Three days in bed","Sport","A trip"],"answer":0}'::jsonb, 'sollen expresses a recommendation or instruction.', 1201) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich brauche einen Termin beim Arzt.","en":"I need an appointment with the doctor.","stress":"ich BRAU-che EI-nen ter-MIN beim ARTST","tip":"Termin stresses the second syllable; Arzt ends in a tst cluster."}'::jsonb, 'Stress pattern: ich BRAU-che EI-nen ter-MIN beim ARTST', 1202) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich möchte einen Termin ___.","en":"I would like to make an appointment.","options":["vereinbaren","kaufen","sagen"],"answer":0}'::jsonb, 'einen Termin vereinbaren is the fixed phrase.', 1203) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Ich","habe","seit","drei","Tagen","Fieber"],"answer":["Ich","habe","seit","drei","Tagen","Fieber"],"en":"I have had a fever for three days."}'::jsonb, 'Duration with seit comes before the symptom.', 1204) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Praxis","en":"the practice"},{"de":"das Rezept","en":"the prescription"},{"de":"die Apotheke","en":"the pharmacy"},{"de":"die Krankschreibung","en":"the sick note"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1205) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Der Arzt ___ mir ein Medikament.","en":"The doctor prescribes me a medicine.","options":["verschreibt","schreibt","gibt"],"answer":0}'::jsonb, 'verschreiben is the medical term for prescribing.', 1206) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You need a sick note for your employer.","question":"How do you ask?","options":["Geben Sie mir einen Zettel.","Könnten Sie mir bitte eine Krankschreibung ausstellen?","Ich brauche Papier."],"answer":1}'::jsonb, 'Use the exact term Krankschreibung with a polite question.', 1207) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('24c32f05-e5d3-5300-a6a6-14decbfced3b'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Rufen Sie schriftlich in einer Praxis an und bitten Sie um einen Termin.', '{"prompt":"Rufen Sie schriftlich in einer Praxis an und bitten Sie um einen Termin.","hint":"Use: Guten Tag, ich hätte gern …, Ich habe …, Vielen Dank.","sample":"Guten Tag, ich hätte gern einen Termin in dieser Woche. Ich habe seit drei Tagen starke Kopfschmerzen. Vielen Dank für Ihre Hilfe."}'::jsonb, 'Use the hint and compare your answer with the model.', 1208) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'transport', 'A1', 'Public Transport', 'Bus & Bahn', 'travel', 'Buy tickets and understand connections.', 13) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Am Fahrkartenautomat', '{"title":"Am Fahrkartenautomat","lines":[{"speaker":"Reisende","de":"Entschuldigung, wie funktioniert der Automat?","en":"Excuse me, how does the machine work?"},{"speaker":"Passant","de":"Zuerst das Ziel wählen, dann bezahlen.","en":"First select the destination, then pay."},{"speaker":"Reisende","de":"Und wie viel kostet eine Einzelfahrt?","en":"And how much is a single ticket?"},{"speaker":"Passant","de":"Drei Euro zwanzig.","en":"Three euros twenty."}],"question":"How much is a single ticket?","options":["2.30","3.20","3.50"],"answer":1}'::jsonb, 'zuerst … dann … orders instructions.', 1300) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mit der U-Bahn', '{"title":"Mit der U-Bahn","text_de":"Ich fahre jeden Tag mit der U-Bahn zur Arbeit. Die Fahrt dauert zwanzig Minuten. Manchmal ist der Zug voll.","text_en":"I take the underground to work every day. The journey takes twenty minutes. Sometimes the train is full.","question":"How long is the journey?","options":["Ten minutes","Twenty minutes","An hour"],"answer":1}'::jsonb, 'mit + dative for means of transport.', 1301) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich fahre mit dem Zug.","en":"I travel by train.","stress":"ich FAH-re mit dem TSUK","tip":"Zug starts with ts and ends with a hard k sound."}'::jsonb, 'Stress pattern: ich FAH-re mit dem TSUK', 1302) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich fahre ___ Bus zur Schule.","en":"I go to school by bus.","options":["mit dem","mit der","in den"],"answer":0}'::jsonb, 'der Bus becomes dem Bus in the dative.', 1303) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wann","fährt","der","nächste","Bus"],"answer":["Wann","fährt","der","nächste","Bus"],"en":"When does the next bus leave?"}'::jsonb, 'Question word first, verb second.', 1304) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Fahrkarte","en":"the ticket"},{"de":"der Bahnsteig","en":"the platform"},{"de":"umsteigen","en":"to change trains"},{"de":"die Verspätung","en":"the delay"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1305) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Der Zug ___ um zehn Uhr ab.","en":"The train departs at ten.","options":["fährt","fahren","gefahren"],"answer":0}'::jsonb, 'abfahren is separable: fährt … ab.', 1306) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A ticket inspector asks for your ticket but you cannot find it.","question":"What do you say?","options":["Ich habe keine.","Einen Moment bitte, ich suche sie kurz.","Später."],"answer":1}'::jsonb, 'Ask for a moment calmly instead of denying.', 1307) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b428119b-04b7-5d56-ae46-96d40752e188'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wie kommen Sie zur Arbeit oder zum Kurs? Drei Sätze.', '{"prompt":"Wie kommen Sie zur Arbeit oder zum Kurs? Drei Sätze.","hint":"Use: Ich fahre mit …, Die Fahrt dauert …, Manchmal …","sample":"Ich fahre mit der Straßenbahn zum Kurs. Die Fahrt dauert eine Viertelstunde. Manchmal gehe ich auch zu Fuß."}'::jsonb, 'Use the hint and compare your answer with the model.', 1308) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'train-station', 'A1', 'At the Station', 'Am Bahnhof', 'travel', 'Ask about platforms, connections and delays.', 14) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Auskunft am Schalter', '{"title":"Auskunft am Schalter","lines":[{"speaker":"Reisender","de":"Wann fährt der nächste Zug nach Köln?","en":"When does the next train to Cologne leave?"},{"speaker":"Beamtin","de":"Um vierzehn Uhr zehn, Gleis sieben.","en":"At 14:10, platform seven."},{"speaker":"Reisender","de":"Muss ich umsteigen?","en":"Do I have to change?"},{"speaker":"Beamtin","de":"Ja, in Hannover.","en":"Yes, in Hanover."}],"question":"Which platform?","options":["Seven","Ten","Fourteen"],"answer":0}'::jsonb, 'Gleis plus number for platforms.', 1400) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die Durchsage', '{"title":"Die Durchsage","text_de":"Achtung am Gleis drei: Der Zug nach Berlin hat zehn Minuten Verspätung. Bitte beachten Sie die Anzeigetafel. Wir bitten um Ihr Verständnis.","text_en":"Attention on platform three: the train to Berlin is ten minutes late. Please note the display board. We ask for your understanding.","question":"What is the delay?","options":["Five minutes","Ten minutes","An hour"],"answer":1}'::jsonb, 'Verspätung haben is the standard phrase for a delay.', 1401) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Der Zug fährt von Gleis vier ab.","en":"The train departs from platform four.","stress":"der TSUK fährt fon GLEIS FIER ab","tip":"ei sounds like eye; the prefix ab is stressed at the end."}'::jsonb, 'Stress pattern: der TSUK fährt fon GLEIS FIER ab', 1402) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Der Zug fährt ___ Gleis zwei.","en":"The train leaves from platform two.","options":["von","aus","an"],"answer":0}'::jsonb, 'von + Gleis for departures.', 1403) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wo","finde","ich","die","Information"],"answer":["Wo","finde","ich","die","Information"],"en":"Where do I find the information desk?"}'::jsonb, 'Question word first, verb second.', 1404) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Gleis","en":"the platform"},{"de":"die Ankunft","en":"the arrival"},{"de":"die Abfahrt","en":"the departure"},{"de":"die Anzeigetafel","en":"the display board"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1405) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich muss in Fulda ___.","en":"I have to change in Fulda.","options":["umsteigen","aussteigen","einsteigen"],"answer":0}'::jsonb, 'umsteigen means to change trains.', 1406) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"Your train is cancelled and you must ask for help.","question":"What is the best opening?","options":["Das ist eine Frechheit!","Entschuldigung, mein Zug fällt aus. Welche Verbindung empfehlen Sie?","Sie sind schuld."],"answer":1}'::jsonb, 'State the problem and ask for a recommendation.', 1407) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6212a8fc-cf68-5457-a1f8-0a0e9212137b'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Fragen Sie schriftlich nach einer Zugverbindung.', '{"prompt":"Fragen Sie schriftlich nach einer Zugverbindung.","hint":"Use: Guten Tag, ich möchte …, Wann …, Muss ich …","sample":"Guten Tag, ich möchte am Freitag nach Hamburg fahren. Wann fährt der erste Zug am Morgen? Muss ich unterwegs umsteigen?"}'::jsonb, 'Use the hint and compare your answer with the model.', 1408) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'telephone', 'A1', 'On the Phone', 'Am Telefon', 'communication', 'Answer calls, spell names and leave messages.', 15) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Ein Anruf', '{"title":"Ein Anruf","lines":[{"speaker":"Frau Kern","de":"Kern, guten Tag.","en":"Kern speaking, hello."},{"speaker":"Anrufer","de":"Guten Tag, hier ist Paulo Silva. Kann ich Herrn Weber sprechen?","en":"Hello, this is Paulo Silva. Can I speak to Mr Weber?"},{"speaker":"Frau Kern","de":"Er ist gerade in einer Besprechung. Soll er zurückrufen?","en":"He is in a meeting right now. Shall he call back?"},{"speaker":"Anrufer","de":"Ja, gern.","en":"Yes, please."}],"question":"Where is Mr Weber?","options":["On holiday","In a meeting","At lunch"],"answer":1}'::jsonb, 'Germans often answer the phone with just their surname.', 1500) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Die Nachricht', '{"title":"Die Nachricht","text_de":"Guten Tag, hier spricht Ana Lima. Ich rufe wegen des Termins am Montag an. Bitte rufen Sie mich unter null eins sieben null zurück.","text_en":"Hello, this is Ana Lima. I am calling about the appointment on Monday. Please call me back on 0170.","question":"Why is she calling?","options":["About Monday''s appointment","About a bill","About a job"],"answer":0}'::jsonb, 'anrufen wegen + genitive/dative explains the reason.', 1501) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Können Sie das bitte buchstabieren?","en":"Could you spell that, please?","stress":"KÖ-nnen sie das BI-tte buch-schta-BIE-ren","tip":"buchstabieren stresses -bie-; the st inside sounds scht here."}'::jsonb, 'Stress pattern: KÖ-nnen sie das BI-tte buch-schta-BIE-ren', 1502) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ ist Herr Lopez.","en":"This is Mr Lopez speaking.","options":["Hier","Da","Dort"],"answer":0}'::jsonb, 'Hier ist … introduces yourself on the phone.', 1503) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Kann","ich","eine","Nachricht","hinterlassen"],"answer":["Kann","ich","eine","Nachricht","hinterlassen"],"en":"Can I leave a message?"}'::jsonb, 'Modal verb first in a yes/no question.', 1504) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Anruf","en":"the call"},{"de":"die Nachricht","en":"the message"},{"de":"die Durchwahl","en":"the extension"},{"de":"besetzt","en":"engaged"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1505) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich rufe später ___.","en":"I will call back later.","options":["zurück","an","auf"],"answer":0}'::jsonb, 'zurückrufen is separable.', 1506) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You reach a wrong number.","question":"What do you say?","options":["Falsch!","Entschuldigung, ich habe mich verwählt.","Wer sind Sie?"],"answer":1}'::jsonb, 'sich verwählen is the polite way to admit a wrong number.', 1507) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('bb9fdfe7-f099-58da-abec-82464bdfa23c'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Hinterlassen Sie schriftlich eine Telefonnachricht.', '{"prompt":"Hinterlassen Sie schriftlich eine Telefonnachricht.","hint":"Use: Guten Tag, hier ist …, Ich rufe wegen … an, Bitte rufen Sie …","sample":"Guten Tag, hier ist Nina Petrova. Ich rufe wegen meines Termins am Mittwoch an. Bitte rufen Sie mich heute Nachmittag zurück."}'::jsonb, 'Use the hint and compare your answer with the model.', 1508) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'invitations', 'A1', 'Invitations & Plans', 'Einladungen & Verabredungen', 'social', 'Invite someone, accept and decline politely.', 16) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Hast du Zeit?', '{"title":"Hast du Zeit?","lines":[{"speaker":"Lina","de":"Hast du am Freitag Zeit?","en":"Do you have time on Friday?"},{"speaker":"Marek","de":"Ja, warum?","en":"Yes, why?"},{"speaker":"Lina","de":"Wir gehen ins Kino. Kommst du mit?","en":"We are going to the cinema. Are you coming along?"},{"speaker":"Marek","de":"Gern, um wie viel Uhr?","en":"Gladly, at what time?"}],"question":"What is the plan?","options":["Cinema","Dinner","Football"],"answer":0}'::jsonb, 'mitkommen is separable: Kommst du mit?', 1600) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Eine Absage', '{"title":"Eine Absage","text_de":"Danke für die Einladung! Leider kann ich am Samstag nicht. Ich habe schon etwas vor. Vielleicht nächste Woche?","text_en":"Thanks for the invitation! Unfortunately I cannot on Saturday. I already have plans. Maybe next week?","question":"Can the writer come?","options":["Yes","No, they have plans","Only later"],"answer":1}'::jsonb, 'etwas vorhaben means to have plans.', 1601) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Hast du Lust, ins Kino zu gehen?","en":"Do you fancy going to the cinema?","stress":"hast du LUST ins KI-no tsu GE-hen","tip":"zu gehen keeps zu unstressed and short."}'::jsonb, 'Stress pattern: hast du LUST ins KI-no tsu GE-hen', 1602) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Hast du am Sonntag ___?","en":"Do you have time on Sunday?","options":["Zeit","Uhr","Termin"],"answer":0}'::jsonb, 'Zeit haben is the fixed phrase.', 1603) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wollen","wir","am","Samstag","essen","gehen"],"answer":["Wollen","wir","am","Samstag","essen","gehen"],"en":"Shall we go out to eat on Saturday?"}'::jsonb, 'Two verbs at the end: essen gehen.', 1604) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"die Einladung","en":"the invitation"},{"de":"absagen","en":"to cancel"},{"de":"zusagen","en":"to accept"},{"de":"sich verabreden","en":"to arrange to meet"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1605) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Leider kann ich ___.","en":"Unfortunately I cannot.","options":["nicht","kein","nichts"],"answer":0}'::jsonb, 'nicht negates the modal verb.', 1606) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You must decline an invitation from a colleague.","question":"Which refusal keeps the relationship warm?","options":["Nein.","Danke für die Einladung! Diesmal schaffe ich es leider nicht, aber nächstes Mal gern.","Keine Zeit."],"answer":1}'::jsonb, 'Thank, decline, and offer an alternative.', 1607) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('af370de7-f6e4-549c-a7ac-cb9fdd8babf4'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Laden Sie eine Freundin zum Essen ein.', '{"prompt":"Laden Sie eine Freundin zum Essen ein.","hint":"Use: Hast du am … Zeit?, Wir könnten …, Sag mir Bescheid.","sample":"Hallo Marie, hast du am Samstag Zeit? Wir könnten zusammen italienisch essen gehen. Sag mir bitte kurz Bescheid."}'::jsonb, 'Use the hint and compare your answer with the model.', 1608) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'likes-dislikes', 'A1', 'Likes & Dislikes', 'Vorlieben & Abneigungen', 'opinions', 'Use mögen, gefallen and schmecken to express taste.', 17) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Schmeckt es dir?', '{"title":"Schmeckt es dir?","lines":[{"speaker":"Gastgeber","de":"Schmeckt dir die Suppe?","en":"Do you like the soup?"},{"speaker":"Gast","de":"Ja, sie schmeckt sehr gut!","en":"Yes, it tastes very good!"},{"speaker":"Gastgeber","de":"Und der Salat?","en":"And the salad?"},{"speaker":"Gast","de":"Den mag ich leider nicht so gern.","en":"That one I unfortunately do not like so much."}],"question":"What does the guest like?","options":["The soup","The salad","Neither"],"answer":0}'::jsonb, 'schmecken takes a dative person: Schmeckt dir …?', 1700) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Geschmackssache', '{"title":"Geschmackssache","text_de":"Mir gefällt die neue Wohnung sehr. Die Farben mag ich nicht so gern, aber das ist Geschmackssache. Am besten gefällt mir der Balkon.","text_en":"I like the new flat a lot. I do not like the colours much, but that is a matter of taste. I like the balcony best.","question":"What does the writer like best?","options":["The colours","The balcony","The kitchen"],"answer":1}'::jsonb, 'gefallen also takes a dative person: mir gefällt …', 1701) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Das gefällt mir sehr gut.","en":"I like that very much.","stress":"das ge-FÄLLT mir sehr GUT","tip":"gefällt stresses the second syllable; ä is open."}'::jsonb, 'Stress pattern: das ge-FÄLLT mir sehr GUT', 1702) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"___ gefällt das Bild.","en":"I like the picture.","options":["Mir","Ich","Mich"],"answer":0}'::jsonb, 'gefallen requires the dative mir.', 1703) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Der","Kuchen","schmeckt","mir","sehr","gut"],"answer":["Der","Kuchen","schmeckt","mir","sehr","gut"],"en":"I like the cake very much."}'::jsonb, 'Dative person after the verb.', 1704) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"mögen","en":"to like"},{"de":"gefallen","en":"to please"},{"de":"lieblings-","en":"favourite"},{"de":"furchtbar","en":"terrible"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1705) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Ich ___ keinen Fisch.","en":"I do not like fish.","options":["mag","magst","mögen"],"answer":0}'::jsonb, 'ich mag is the first person of mögen.', 1706) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You are served a dish you dislike at someone''s home.","question":"What is polite?","options":["Das schmeckt schrecklich.","Danke, das ist nicht ganz mein Geschmack, aber sehr nett von dir.","Ich esse das nicht."],"answer":1}'::jsonb, 'Soften the refusal and thank the host.', 1707) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('da9b3397-3c2c-55d5-a45f-b0f894b13f03'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Was mögen Sie und was nicht? Drei Sätze.', '{"prompt":"Was mögen Sie und was nicht? Drei Sätze.","hint":"Use: Ich mag …, … gefällt mir …, … schmeckt mir nicht.","sample":"Ich mag deutsches Brot sehr. Klassische Musik gefällt mir gut. Kaffee ohne Zucker schmeckt mir leider nicht."}'::jsonb, 'Use the hint and compare your answer with the model.', 1708) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'animals-nature', 'A1', 'Animals & Nature', 'Tiere & Natur', 'nature', 'Talk about pets, animals and being outdoors.', 18) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Hast du ein Haustier?', '{"title":"Hast du ein Haustier?","lines":[{"speaker":"Ida","de":"Hast du ein Haustier?","en":"Do you have a pet?"},{"speaker":"Nico","de":"Ja, einen Hund. Er heißt Bruno.","en":"Yes, a dog. His name is Bruno."},{"speaker":"Ida","de":"Wie alt ist er?","en":"How old is he?"},{"speaker":"Nico","de":"Drei Jahre. Er läuft gern im Wald.","en":"Three years. He likes running in the forest."}],"question":"What pet does Nico have?","options":["A cat","A dog","A bird"],"answer":1}'::jsonb, 'ein Haustier haben takes the accusative: einen Hund.', 1800) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Im Wald', '{"title":"Im Wald","text_de":"Am Wochenende gehen wir gern im Wald spazieren. Dort sieht man manchmal Rehe und viele Vögel. Die Luft ist frisch und es ist sehr ruhig.","text_en":"At the weekend we like walking in the forest. There you sometimes see deer and many birds. The air is fresh and it is very quiet.","question":"What can you see there?","options":["Deer and birds","Fish","Horses"],"answer":0}'::jsonb, 'man sieht is the impersonal you see.', 1801) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Mein Hund läuft gern im Wald.","en":"My dog likes running in the forest.","stress":"mein HUND läuft gern im VALD","tip":"The German w in Wald is a v; the final d sounds like t."}'::jsonb, 'Stress pattern: mein HUND läuft gern im VALD', 1802) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich habe ___ Katze.","en":"I have a cat.","options":["eine","einen","ein"],"answer":0}'::jsonb, 'die Katze stays eine in the accusative.', 1803) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Wir","gehen","im","Park","spazieren"],"answer":["Wir","gehen","im","Park","spazieren"],"en":"We go for a walk in the park."}'::jsonb, 'spazieren gehen keeps both verbs at the end.', 1804) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Hund","en":"the dog"},{"de":"die Katze","en":"the cat"},{"de":"der Baum","en":"the tree"},{"de":"der See","en":"the lake"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1805) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Die Vögel ___ im Garten.","en":"The birds sing in the garden.","options":["singen","singt","gesungen"],"answer":0}'::jsonb, 'Plural subject takes the -en ending.', 1806) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"A dog runs towards you and the owner is nearby.","question":"What can you ask?","options":["Nehmen Sie den Hund weg!","Ist er freundlich? Darf ich ihn streicheln?","Hunde sind verboten."],"answer":1}'::jsonb, 'Ask before touching someone''s dog.', 1807) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('b2c1cb06-8bea-5cf9-a784-c5219a73fea4'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie ein Tier, das Sie mögen. Drei Sätze.', '{"prompt":"Beschreiben Sie ein Tier, das Sie mögen. Drei Sätze.","hint":"Use: Ich mag …, Es ist …, Am liebsten …","sample":"Ich mag Katzen sehr. Sie sind ruhig und sehr selbstständig. Am liebsten sitze ich abends mit einer Katze auf dem Sofa."}'::jsonb, 'Use the hint and compare your answer with the model.', 1808) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'city-country', 'A1', 'City & Countryside', 'Stadt & Land', 'places', 'Compare living in a city and in a village in simple terms.', 19) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Stadt oder Dorf?', '{"title":"Stadt oder Dorf?","lines":[{"speaker":"Ravi","de":"Wohnst du gern in der Stadt?","en":"Do you like living in the city?"},{"speaker":"Hanna","de":"Ja, alles ist nah. Aber es ist laut.","en":"Yes, everything is close. But it is loud."},{"speaker":"Ravi","de":"Ich wohne auf dem Land. Dort ist es ruhig.","en":"I live in the countryside. It is quiet there."}],"question":"Where does Ravi live?","options":["In the city","In the countryside","By the sea"],"answer":1}'::jsonb, 'auf dem Land is the fixed phrase for the countryside.', 1900) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Ort', '{"title":"Mein Ort","text_de":"Ich wohne in einer Kleinstadt mit zwanzigtausend Einwohnern. Es gibt einen Marktplatz, zwei Schulen und ein Schwimmbad. Zum Einkaufen fahre ich in die große Stadt.","text_en":"I live in a small town with twenty thousand inhabitants. There is a market square, two schools and a swimming pool. For shopping I drive to the big city.","question":"How many inhabitants?","options":["2,000","20,000","200,000"],"answer":1}'::jsonb, 'Es gibt + accusative lists what exists in a place.', 1901) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Ich wohne auf dem Land.","en":"I live in the countryside.","stress":"ich WOH-ne auf dem LAND","tip":"The final d in Land sounds like t."}'::jsonb, 'Stress pattern: ich WOH-ne auf dem LAND', 1902) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich wohne ___ der Stadt.","en":"I live in the city.","options":["in","auf","an"],"answer":0}'::jsonb, 'in der Stadt versus auf dem Land.', 1903) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["In","meiner","Stadt","gibt","es","viele","Cafés"],"answer":["In","meiner","Stadt","gibt","es","viele","Cafés"],"en":"In my city there are many cafés."}'::jsonb, 'Place first, then gibt es.', 1904) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"das Dorf","en":"the village"},{"de":"die Einwohner","en":"the inhabitants"},{"de":"laut","en":"loud"},{"de":"ruhig","en":"quiet"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 1905) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"___ gibt hier einen Park.","en":"There is a park here.","options":["Es","Das","Da"],"answer":0}'::jsonb, 'Es gibt is the fixed existential phrase.', 1906) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"Someone criticises the town you live in.","question":"How do you answer politely but honestly?","options":["Du hast keine Ahnung.","Stimmt, es ist klein, aber mir gefällt die Ruhe.","Egal."],"answer":1}'::jsonb, 'Agree partly, then add your own view.', 1907) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('6e61dab8-0855-58b1-a0ba-11015d93a620'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Wo wohnen Sie und wie ist es dort? Drei Sätze.', '{"prompt":"Wo wohnen Sie und wie ist es dort? Drei Sätze.","hint":"Use: Ich wohne in …, Es gibt …, Mir gefällt …","sample":"Ich wohne in einer mittelgroßen Stadt im Süden. Es gibt viele Cafés und einen großen Park. Mir gefällt besonders, dass alles zu Fuß erreichbar ist."}'::jsonb, 'Use the hint and compare your answer with the model.', 1908) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.lessons (id, slug, level, title, title_de, theme, summary, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'a1-recap', 'A1', 'A1 Recap & Everyday Survival', 'A1 Wiederholung', 'review', 'Combine greetings, shopping, time and directions in real situations.', 20) ON CONFLICT (slug) DO UPDATE SET level = EXCLUDED.level, title = EXCLUDED.title, title_de = EXCLUDED.title_de, theme = EXCLUDED.theme, summary = EXCLUDED.summary, order_index = EXCLUDED.order_index;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'input', 'phonology', 'listening', 'audio_dialogue', 'Listen to the dialogue: Ein normaler Tag', '{"title":"Ein normaler Tag","lines":[{"speaker":"Nachbarin","de":"Guten Morgen! Wohin gehen Sie so früh?","en":"Good morning! Where are you going so early?"},{"speaker":"Sie","de":"Guten Morgen! Ich gehe einkaufen und dann zum Arzt.","en":"Good morning! I am going shopping and then to the doctor."},{"speaker":"Nachbarin","de":"Dann einen schönen Tag!","en":"Have a nice day then!"},{"speaker":"Sie","de":"Danke, Ihnen auch.","en":"Thanks, you too."}],"question":"Where is the speaker going after shopping?","options":["Home","To the doctor","To work"],"answer":1}'::jsonb, 'zum Arzt uses zu + dem for people and institutions.', 2000) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'input', 'semantics', 'reading', 'reading_passage', 'Read the passage: Mein Tag', '{"title":"Mein Tag","text_de":"Ich stehe um halb sieben auf und trinke Kaffee. Um acht fahre ich mit dem Bus zur Arbeit. Am Abend koche ich und sehe ein bisschen fern.","text_en":"I get up at half past six and drink coffee. At eight I take the bus to work. In the evening I cook and watch a bit of television.","question":"When does the writer get up?","options":["06:30","07:30","08:00"],"answer":0}'::jsonb, 'halb sieben means half an hour before seven.', 2001) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'output', 'phonology', 'speaking', 'pronounce', 'Repeat the sentence after the example.', '{"target_de":"Entschuldigung, wie komme ich zum Bahnhof?","en":"Excuse me, how do I get to the station?","stress":"ent-SCHUL-di-gung wie KO-mme ich tsum BAHN-hof","tip":"Keep Entschuldigung fluent; the stress sits on -schul-."}'::jsonb, 'Stress pattern: ent-SCHUL-di-gung wie KO-mme ich tsum BAHN-hof', 2002) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'output', 'morphology', 'writing', 'fill_blank', 'Choose the word that completes the sentence.', '{"sentence":"Ich stehe um sieben Uhr ___.","en":"I get up at seven.","options":["auf","an","aus"],"answer":0}'::jsonb, 'aufstehen is separable.', 2003) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'output', 'syntax', 'writing', 'word_order', 'Build the German sentence in the right order.', '{"tokens":["Am","Abend","koche","ich","gern","zu","Hause"],"answer":["Am","Abend","koche","ich","gern","zu","Hause"],"en":"In the evening I like cooking at home."}'::jsonb, 'Time first, verb second, place at the end.', 2004) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'output', 'semantics', 'reading', 'vocab_match', 'Match each German word with its English meaning.', '{"pairs":[{"de":"der Alltag","en":"everyday life"},{"de":"früh","en":"early"},{"de":"spät","en":"late"},{"de":"zu Fuß","en":"on foot"}]}'::jsonb, 'Vocabulary matching builds recognition in both directions.', 2005) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'feedback', 'morphology', 'writing', 'fill_blank', 'Review: choose the word that completes the sentence.', '{"sentence":"Wie komme ich ___ Bahnhof?","en":"How do I get to the station?","options":["zum","zur","nach"],"answer":0}'::jsonb, 'der Bahnhof takes zum.', 2006) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'feedback', 'pragmatics', 'reading', 'pragmatics_choice', 'What is the most appropriate response in this situation?', '{"scenario":"You meet your neighbour in the stairwell in the morning.","question":"What do you say?","options":["Nichts.","Guten Morgen! Schönen Tag noch.","Was wollen Sie?"],"answer":1}'::jsonb, 'A short greeting is expected in German buildings.', 2007) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (lesson_id, phase, dimension, skill, type, prompt, content, explanation, order_index) VALUES ('57dc2a97-3801-5d9f-a9ae-eb0f35c99863'::uuid, 'output', 'pragmatics', 'writing', 'writing_prompt', 'Beschreiben Sie Ihren normalen Tag in vier Sätzen.', '{"prompt":"Beschreiben Sie Ihren normalen Tag in vier Sätzen.","hint":"Use: Ich stehe … auf, Dann …, Am Nachmittag …, Am Abend …","sample":"Ich stehe um sechs Uhr auf und frühstücke. Dann fahre ich mit der Bahn zur Arbeit. Am Nachmittag kaufe ich schnell ein. Am Abend koche ich und lese ein Buch."}'::jsonb, 'Use the hint and compare your answer with the model.', 2008) ON CONFLICT (id) DO NOTHING;
